from collections import deque
def transform(g):
    h,w=len(g),len(g[0])
    bg=max(set(x for r in g for x in r), key=[x for r in g for x in r].count)
    shape=[v for v in set(x for r in g for x in r) if v!=bg]
    shape=shape[0] if shape else bg
    out=[r[:] for r in g]
    seen=[[False]*w for _ in range(h)]
    q=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]==bg and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]==bg and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and g[ni][nj]==bg and not seen[ni][nj]:
                seen[ni][nj]=True; q.append((ni,nj))
    for i in range(h):
        for j in range(w):
            if g[i][j]==bg and not seen[i][j]: out[i][j]=4
    return out
